const cloud = require('wx-server-sdk')
cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV })
const db = cloud.database()
const _ = db.command

exports.main = async function(event, context) {
  const wxContext = cloud.getWXContext()
  const openid = wxContext.OPENID
  const orderId = event.orderId
  const reason = event.reason || ''

  if (!orderId) {
    return { code: -1, msg: '缺少订单ID' }
  }

  try {
    const orderResult = await db.collection('orders').doc(orderId).get()
    if (!orderResult.data) {
      return { code: -1, msg: '订单不存在' }
    }
    const order = orderResult.data

    if (order.acceptorId !== openid) {
      return { code: -1, msg: '只有接单者可以取消接单' }
    }
    if (order.status !== 'accepted') {
      return { code: -1, msg: '订单状态不正确' }
    }

    if (!reason || reason.trim().length === 0) {
      return { code: -1, msg: '请填写取消理由' }
    }

    const now = db.serverDate()
    await db.collection('orders').doc(orderId).update({
      data: {
        status: 'pending',
        acceptorId: '',
        acceptorName: '',
        acceptorPhone: '',
        acceptTime: '',
        cancelReason: '接单人取消接单：' + reason.trim(),
        acceptorCancelReason: reason.trim(),
        cancelledByAcceptor: true
      }
    })

    // helpCount 递减时加下界保护，防止变为负数
    await db.collection('users').where({
      _openid: openid,
      helpCount: _.gt(0)
    }).update({
      data: { helpCount: _.inc(-1) }
    })

    // 发送系统消息通知发布者
    try {
      await db.collection('messages').add({
        data: {
          orderId: orderId,
          senderId: 'system',
          receiverId: order.publisherId,
          content: '接单人已取消接单，理由：' + reason.trim() + '。订单已重新发布到接单广场。',
          type: 'system',
          createTime: now,
          isRead: false
        }
      })
    } catch (msgErr) {
      console.log('[帮到位] 取消接单时通知消息发送失败（不影响主流程）', msgErr.message)
    }

    try {
      await db.collection('messages').where({
        orderId: orderId,
        isRead: false
      }).update({
        data: { isRead: true }
      })
    } catch (msgErr) {
      console.log('[帮到位] 取消接单时消息清理失败（不影响主流程）', msgErr.message)
    }

    return { code: 0, msg: '已取消接单' }
  } catch (err) {
    return { code: -1, msg: '操作失败', err: err.message }
  }
}
