const cloud = require('wx-server-sdk')
cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV })
const db = cloud.database()
const _ = db.command

exports.main = async function(event, context) {
  const wxContext = cloud.getWXContext()
  const openid = wxContext.OPENID
  const orderId = event.orderId

  if (!orderId) {
    return { code: -1, msg: '缺少订单ID' }
  }

  try {
    const orderResult = await db.collection('orders').doc(orderId).get()
    if (!orderResult.data) {
      return { code: -1, msg: '订单不存在' }
    }
    const order = orderResult.data

    if (order.publisherId !== openid) {
      return { code: -1, msg: '只有发布者可以确认付款' }
    }
    if (order.status !== 'delivered') {
      return { code: -1, msg: '订单状态不正确' }
    }

    await db.collection('orders').doc(orderId).update({
      data: {
        status: 'paid',
        paymentTime: db.serverDate()
      }
    })

    // 星分规则调整：确认付款不再额外加星分
    // 星分来源：确认送达时双方各+1（基础分），评价时4星+1/5星+2
    // helpCount 在 acceptOrder 接单时已 +1，不重复递增

    try {
      await cloud.callFunction({
        name: 'sendNotification',
        data: {
          touser: order.acceptorId,
          templateId: 'qPvZ40UXg3Qcf49klooCPyBkBkUoNjBdKcjgBX6iGIk',
          page: 'pages/order-detail/order-detail?id=' + orderId,
          data: {
            amount1: { value: order.price ? order.price + '元' : '0元' },
            character_string3: { value: order.orderNo || '' },
            name5: { value: order.publisherName || '同学' },
            date6: { value: new Date().toLocaleDateString('zh-CN') },
            thing4: { value: '已完成，感谢使用帮到位' }
          }
        }
      })
    } catch (notifyErr) {
      console.log('[帮到位] 通知发送失败（不影响主流程）', notifyErr.message)
    }

    return { code: 0, msg: '确认付款成功' }
  } catch (err) {
    return { code: -1, msg: '操作失败', err: err.message }
  }
}
