// complainOrder/index.js
// 云函数：投诉订单（只记录投诉，不自动扣分，由管理员审核处理）
var cloud = require('wx-server-sdk')
cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV })
var db = cloud.database()

exports.main = function (event, context) {
  var wxContext = cloud.getWXContext()
  var openid = wxContext.OPENID
  var orderId = event.orderId
  var reason = event.reason || ''

  if (!orderId) {
    return { code: -1, msg: '缺少订单ID' }
  }

  return db.collection('orders').doc(orderId).get().then(function (orderResult) {
    if (!orderResult.data) {
      return { code: -1, msg: '订单不存在' }
    }
    var order = orderResult.data

    // 只有订单参与者（发布者或接单者）可以投诉
    if (order.publisherId !== openid && order.acceptorId !== openid) {
      return { code: -1, msg: '无权操作此订单' }
    }

    // 待接单状态不允许投诉
    if (order.status === 'pending') {
      return { code: -1, msg: '订单待接单，无法投诉' }
    }

    // 防重复投诉：同一订单同一用户只能投诉一次
    if (order.complain && order.complain.complainantId === openid) {
      return { code: -1, msg: '您已投诉过此订单' }
    }

    // 确定被投诉者
    var targetId = ''
    var targetName = ''
    var complainantName = ''
    if (order.publisherId === openid) {
      targetId = order.acceptorId
      targetName = order.acceptorName
      complainantName = order.publisherName
    } else {
      targetId = order.publisherId
      targetName = order.publisherName
      complainantName = order.acceptorName
    }

    if (!targetId) {
      return { code: -1, msg: '无法确定投诉对象' }
    }

    // 记录投诉信息到订单
    var complainData = {
      complain: {
        complainantId: openid,
        targetId: targetId,
        reason: reason,
        time: db.serverDate()
      }
    }

    return db.collection('orders').doc(orderId).update({
      data: complainData
    }).then(function () {
      // 写入投诉集合，等待管理员审核处理
      return db.collection('complaints').add({
        data: {
          orderId: orderId,
          orderNo: order.orderNo || '',
          complainantId: openid,
          complainantName: complainantName || '',
          targetId: targetId,
          targetUserName: targetName || '',
          content: reason,
          status: 'pending',
          createTime: db.serverDate()
        }
      })
    })
  }).then(function () {
    return { code: 0, msg: '投诉已提交，等待管理员处理' }
  }).catch(function (err) {
    return { code: -1, msg: '操作失败', err: err.message }
  })
}
