const cloud = require('wx-server-sdk')
cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV })
const db = cloud.database()
const _ = db.command

/**
 * 将云存储 fileID 列表转换为临时 URL
 */
async function convertFileIDsToURLs(fileIDs) {
  if (!fileIDs || fileIDs.length === 0) return []
  // 过滤掉非 fileID 格式（已经是 http URL 的不用转换）
  var needConvert = []
  var resultMap = {}
  for (var i = 0; i < fileIDs.length; i++) {
    var id = fileIDs[i]
    if (typeof id === 'string' && id.indexOf('cloud://') === 0) {
      needConvert.push(id)
      resultMap[id] = id // 默认fallback
    } else {
      resultMap[id] = id
    }
  }
  if (needConvert.length === 0) return fileIDs

  try {
    var convertRes = await cloud.getTempFileURL({ fileList: needConvert })
    if (convertRes && convertRes.fileList) {
      for (var j = 0; j < convertRes.fileList.length; j++) {
        var item = convertRes.fileList[j]
        if (item.tempFileURL) {
          resultMap[item.fileID] = item.tempFileURL
        }
      }
    }
  } catch (e) {
    console.log('[getOrders] 转换图片URL失败', e.message)
  }

  var results = []
  for (var k = 0; k < fileIDs.length; k++) {
    results.push(resultMap[fileIDs[k]] || fileIDs[k])
  }
  return results
}

/**
 * 处理订单列表中的图片URL
 */
async function processOrderImages(list) {
  // 收集所有需要转换的fileID
  var allFileIDs = []
  var orderImageMap = [] // 记录每个订单的图片字段位置

  for (var i = 0; i < list.length; i++) {
    var order = list[i]
    if (order.productImages && order.productImages.length > 0) {
      for (var p = 0; p < order.productImages.length; p++) {
        allFileIDs.push(order.productImages[p])
        orderImageMap.push({ index: i, field: 'productImages', subIndex: p })
      }
    }
    if (order.otherImages && order.otherImages.length > 0) {
      for (var o = 0; o < order.otherImages.length; o++) {
        allFileIDs.push(order.otherImages[o])
        orderImageMap.push({ index: i, field: 'otherImages', subIndex: o })
      }
    }
    if (order.deliveryPhoto && typeof order.deliveryPhoto === 'string' && order.deliveryPhoto.indexOf('cloud://') === 0) {
      allFileIDs.push(order.deliveryPhoto)
      orderImageMap.push({ index: i, field: 'deliveryPhoto', subIndex: -1 })
    }
  }

  if (allFileIDs.length === 0) return

  // 去重，减少API调用
  var uniqueFileIDs = []
  var seen = {}
  for (var u = 0; u < allFileIDs.length; u++) {
    if (!seen[allFileIDs[u]]) {
      seen[allFileIDs[u]] = true
      uniqueFileIDs.push(allFileIDs[u])
    }
  }

  // 分批转换（每次最多50个）
  var urlMap = {}
  var batchSize = 50
  for (var b = 0; b < uniqueFileIDs.length; b += batchSize) {
    var batch = uniqueFileIDs.slice(b, b + batchSize)
    try {
      var res = await cloud.getTempFileURL({ fileList: batch })
      if (res && res.fileList) {
        for (var f = 0; f < res.fileList.length; f++) {
          var fileItem = res.fileList[f]
          if (fileItem.tempFileURL) {
            urlMap[fileItem.fileID] = fileItem.tempFileURL
          }
        }
      }
    } catch (e) {
      console.log('[getOrders] 批量转换图片URL失败', e.message)
    }
  }

  // 回填转换后的URL到订单数据
  for (var m = 0; m < orderImageMap.length; m++) {
    var map = orderImageMap[m]
    var originalID = list[map.index][map.field]
    if (map.subIndex >= 0) {
      originalID = list[map.index][map.field][map.subIndex]
    }
    if (urlMap[originalID]) {
      if (map.subIndex >= 0) {
        list[map.index][map.field][map.subIndex] = urlMap[originalID]
      } else {
        list[map.index][map.field] = urlMap[originalID]
      }
    }
  }
}

/**
 * 查询用户的管理员状态
 */
async function getAdminStatus(openid) {
  try {
    const userRes = await db.collection('users').where({ _openid: openid }).get()
    if (userRes.data && userRes.data.length > 0) {
      const user = userRes.data[0]
      return user.isAdmin || user.isManager || user.isFounder
    }
  } catch (e) {}
  return false
}

exports.main = async function(event) {
  const wxContext = cloud.getWXContext()
  const openid = wxContext.OPENID
  const viewType = event.viewType || 'all'
  const status = event.status || ''
  const category = event.category || ''
  const page = event.page || 1
  const pageSize = Math.min(event.pageSize || 10, 50)
  const keyword = event.keyword || ''
  const sortBy = event.sortBy || 'newest'

  try {
    var conditions = []

    if (viewType === 'mine') {
      conditions.push({ publisherId: openid })
    } else if (viewType === 'accept') {
      conditions.push({ acceptorId: openid })
    } else {
      conditions.push({ status: _.neq('cancelled') })
    }

    if (status && status !== 'all') {
      conditions.push({ status: status })
    }

    if (category && category !== 'all') {
      if (category === 'water') {
        conditions.push(_.or([
          { category: 'water' },
          { category: _.exists(false) }
        ]))
      } else {
        conditions.push({ category: category })
      }
    }

    if (keyword) {
      conditions.push({ remark: db.RegExp({ regexp: keyword, options: 'i' }) })
    }

    var whereCondition = conditions.length > 0 ? _.and(conditions) : {}

    var orderQuery = db.collection('orders').where(whereCondition)
    
    if (sortBy === 'price_asc') {
      orderQuery = orderQuery.orderBy('price', 'asc')
    } else if (sortBy === 'price_desc') {
      orderQuery = orderQuery.orderBy('price', 'desc')
    } else {
      orderQuery = orderQuery.orderBy('createTime', 'desc')
    }
    
    const orders = await orderQuery
      .skip((page - 1) * pageSize)
      .limit(pageSize + 1)
      .get()

    var list = orders.data || []
    var hasMore = list.length > pageSize
    if (hasMore) {
      list = list.slice(0, pageSize)
    }

    var categoryMap = { water: '搬水', errand: '跑腿', substitute: '代课', secondhand: '二手', other: '其他' }
    var countUnitMap = { water: '桶', errand: '件', substitute: '节', secondhand: '件', other: '份' }
    var statusMap = {
      pending: '待接单',
      accepted: '进行中',
      delivered: '待付款',
      paid: '已完成',
      cancelled: '已取消',
      expired: '已过期'
    }

    // 使用聚合查询关联用户信息，一次性获取所有发布者的详细信息
    var publisherIds = []
    for (var i = 0; i < list.length; i++) {
      if (list[i].publisherId && publisherIds.indexOf(list[i].publisherId) === -1) {
        publisherIds.push(list[i].publisherId)
      }
    }

    var userMap = {}
    if (publisherIds.length > 0) {
      var userRes = await db.collection('users').where({
        _openid: _.in(publisherIds)
      }).get()
      for (var j = 0; j < userRes.data.length; j++) {
        var user = userRes.data[j]
        if (user._openid) userMap[user._openid] = user
      }
    }

    const now = Date.now()
    const thirtyDaysAgo = now - 30 * 24 * 60 * 60 * 1000

    for (var k = 0; k < list.length; k++) {
      var item = list[k]
      if (!item.category) item.category = 'water'
      item.categoryText = categoryMap[item.category] || '其他'

      if (item.status === 'pending') {
        if (['water', 'errand', 'substitute'].indexOf(item.category) !== -1) {
          if (item.deliveryTime) {
            var deliveryTime = new Date(item.deliveryTime).getTime()
            if (deliveryTime < now) {
              item.status = 'expired'
              item.isExpired = true
            }
          }
        }
      }
      if (item.status === 'pending' && item.category === 'secondhand') {
        if (item.createTime) {
          var createTime = new Date(item.createTime).getTime()
          if (createTime < thirtyDaysAgo) {
            item.status = 'expired'
            item.isExpired = true
          }
        }
      }

      item.statusText = statusMap[item.status] || '未知'
      item.isMine = item.publisherId === openid
      if (item.count) {
        var unit = countUnitMap[item.category] || '份'
        item.countText = '共' + item.count + unit
      }
      // 只按openid精确匹配，避免手机号相同导致身份混淆
      var publisherUser = userMap[item.publisherId]
      if (publisherUser) {
        item.publisherName = publisherUser.nickName || item.publisherName || '用户'
        // 身份角色：创始人/管理员是独立标签，不参与星级计算
        // 兼容数据库中字段名可能带空格的情况（如 'isManager '）
        var isAdmin = publisherUser.isAdmin || publisherUser['isAdmin ']
        var isManager = publisherUser.isManager || publisherUser['isManager ']
        if (isAdmin) {
          item.publisherRole = 'founder'
          item.publisherRoleText = '👑 创始人'
        } else if (isManager) {
          item.publisherRole = 'manager'
          item.publisherRoleText = '🌙 管理员'
        }
        // 八大行星体系：新用户从0分1星开始，每25星分升1级，最高8星
        if (!item.publisherRole) {
          var starPoints = (publisherUser.starPoints !== undefined && publisherUser.starPoints !== null) ? publisherUser.starPoints : 0
          item.publisherStarLevel = Math.max(1, Math.min(10, Math.floor(starPoints / 50) + 1))
        }
      } else {
        item.publisherName = item.publisherName || '用户'
        item.publisherStarLevel = item.publisherStarLevel || 1
      }
    }

    // 不在这里转换图片URL，让前端异步转换，加快响应速度
    // 前端会通过 wx.cloud.getTempFileURL 批量转换并缓存

    return {
      code: 0,
      data: {
        orders: list,
        hasMore: hasMore,
        currentOpenid: openid,
        isAdmin: !!(await getAdminStatus(openid))
      }
    }
  } catch (err) {
    return { code: -1, msg: err.message }
  }
}
