// 云函数：发送聊天消息
const cloud = require('wx-server-sdk')
cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV })
const db = cloud.database()

function formatDate(date) {
  var y = date.getFullYear()
  var m = ('0' + (date.getMonth() + 1)).slice(-2)
  var d = ('0' + date.getDate()).slice(-2)
  var h = ('0' + date.getHours()).slice(-2)
  var min = ('0' + date.getMinutes()).slice(-2)
  var s = ('0' + date.getSeconds()).slice(-2)
  return y + '-' + m + '-' + d + ' ' + h + ':' + min + ':' + s
}

exports.main = async function(event, context) {
  const wxContext = cloud.getWXContext()
  const openid = wxContext.OPENID
  const orderId = event.orderId
  const content = (event.content || '').trim()
  const imageUrl = event.imageUrl || ''

  if (!orderId || (!content && !imageUrl)) {
    return { code: -1, msg: '参数不完整' }
  }

  // 文本消息长度限制
  if (!imageUrl && content.length > 500) {
    return { code: -1, msg: '消息不能超过500字' }
  }

  // ===== 频率限制：同一用户对同一订单10秒内最多发3条 =====
  try {
    const tenSecAgo = new Date(Date.now() - 10000)
    const recentMsgs = await db.collection('messages').where({
      orderId: orderId,
      senderId: openid,
      createTime: db.command.gte(tenSecAgo)
    }).count()
    if (recentMsgs.total >= 3) {
      return { code: -1, msg: '发送太频繁，请稍后再试' }
    }
  } catch (rateLimitErr) {
    // 频率检查失败不阻塞主流程
    console.log('[帮到位] 消息频率检查失败（不阻塞主流程）', rateLimitErr.message)
  }

  try {
    // 验证订单存在
    const orderResult = await db.collection('orders').doc(orderId).get()
    if (!orderResult.data) {
      return { code: -1, msg: '订单不存在' }
    }

    const order = orderResult.data
    // 发布者始终可以发消息
    if (order.publisherId !== openid) {
      // 非发布者必须是接单者才能发消息
      if (!order.acceptorId || order.acceptorId === '' || order.acceptorId !== openid) {
        return { code: -1, msg: '无权发送消息' }
      }
    }

    // 订单取消后不再接受新消息（已完成的订单仍可聊天）
    if (order.status === 'cancelled') {
      return { code: -1, msg: '订单已取消，无法发送消息' }
    }

    // 获取发送者昵称
    var senderName = '匿名用户'
    if (order.publisherId === openid) {
      senderName = order.publisherName || '匿名用户'
    } else {
      senderName = order.acceptorName || '匿名用户'
    }

    // 写入消息记录
    const msgResult = await db.collection('messages').add({
      data: {
        orderId: orderId,
        orderNo: order.orderNo || '',
        senderId: openid,
        senderName: senderName,
        content: content,
        imageUrl: imageUrl,
        isRead: false,
        createTime: db.serverDate()
      }
    })

    // 发送订阅消息通知对方（异步发送，不阻塞消息写入）
    try {
      var targetOpenId = order.publisherId === openid ? order.acceptorId : order.publisherId
      var targetName = targetOpenId === order.publisherId ? (order.publisherName || '同学') : (order.acceptorName || '同学')
      cloud.callFunction({
        name: 'sendNotification',
        data: {
          touser: targetOpenId,
          templateId: 'aJxK4rE20mPEBeFS4LJyxTFGwsh9VK5AvqLKA6Juh-w',
          page: 'pages/chat/chat?id=' + orderId,
          data: {
            thing4: { value: senderName || '同学' },
            thing2: { value: (content || '图片消息').substring(0, 20) },
            time3: { value: formatDate(new Date()) },
            phrase8: { value: imageUrl ? '图片消息' : '文字消息' },
            thing9: { value: targetName }
          }
        }
      })
    } catch (notifyErr) {
      console.log('通知发送失败:', notifyErr)
    }

    return {
      code: 0,
      msg: '发送成功',
      data: {
        _id: msgResult._id,
        orderId: orderId,
        senderId: openid,
        senderName: senderName,
        content: content,
        imageUrl: imageUrl,
        isRead: false,
        createTime: new Date().toISOString()
      }
    }
  } catch (err) {
    return { code: -1, msg: '发送失败', err: err.message }
  }
}
