// rateOrder/index.js
// 云函数：评价订单
const cloud = require('wx-server-sdk')
cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV })
const db = cloud.database()
const _ = db.command

exports.main = async function(event, context) {
  const wxContext = cloud.getWXContext()
  const openid = wxContext.OPENID
  const orderId = event.orderId
  const score = parseInt(event.score)  // 1-5 分
  const content = (event.content || '').trim()

  if (!orderId || !score) {
    return { code: -1, msg: '缺少参数' }
  }
  if (isNaN(score) || score < 1 || score > 5) {
    return { code: -1, msg: '评分必须在1-5之间' }
  }

  // 评价内容长度限制
  if (content.length > 200) {
    return { code: -1, msg: '评价内容不能超过200字' }
  }

  try {
    // 检查订单
    const orderResult = await db.collection('orders').doc(orderId).get()
    if (!orderResult.data) {
      return { code: -1, msg: '订单不存在' }
    }
    const order = orderResult.data

    if (order.status !== 'paid') {
      return { code: -1, msg: '订单未完成，无法评价' }
    }

    // ===== 防重复评价：检查 reviews 集合中是否已有记录 =====
    const existingReview = await db.collection('reviews').where({
      orderId: orderId,
      reviewerId: openid
    }).count()
    if (existingReview.total > 0) {
      return { code: -1, msg: '已评价过，不能重复评价' }
    }

    // 只有订单的发布者或接单者可以评价
    if (openid !== order.publisherId && openid !== order.acceptorId) {
      return { code: -1, msg: '只有订单参与者可以评价' }
    }

    // 获取评价者信息
    const userResult = await db.collection('users').where({ _openid: openid }).get()
    const reviewerName = userResult.data.length > 0 ? userResult.data[0].nickName : '匿名'

    // 确定被评价者：如果是发布者评价，被评价者是接单者；反之亦然
    var targetId = ''
    var targetName = ''
    if (openid === order.publisherId) {
      targetId = order.acceptorId
      targetName = order.acceptorName
    } else {
      targetId = order.publisherId
      targetName = order.publisherName
    }

    // 写入评价
    await db.collection('reviews').add({
      data: {
        orderId: orderId,
        orderNo: order.orderNo,
        reviewerId: openid,
        reviewerName: reviewerName,
        targetId: targetId,
        targetName: targetName,
        score: score,
        content: content,
        createTime: db.serverDate()
      }
    })

    // 更新订单评价信息（原子条件更新，防止并发双加星分）
    var orderUpdateResult = await db.collection('orders').where({
      _id: orderId,
      rating: _.exists(false)
    }).update({
      data: {
        rating: score,
        reviewContent: content
      }
    })

    // 如果没有更新成功，说明已被评价过（并发请求）
    if (orderUpdateResult.stats.updated === 0) {
      return { code: -1, msg: '该订单已被评价过' }
    }

    // 更新被评价者的评分（加权平均）
    var targetUserResult = await db.collection('users').where({ _openid: targetId }).get()
    if (targetUserResult.data.length > 0) {
      var targetUser = targetUserResult.data[0]
      var oldRating = targetUser.rating || 0
      var oldCount = targetUser.ratingCount || 0
      var newCount = oldCount + 1
      var newRating = ((oldRating * oldCount) + score) / newCount
      // 保留一位小数
      newRating = Math.round(newRating * 10) / 10

      // 星分规则：
      // 评价1-3星：不加额外星分，只更新评分值
      // 评价4星：+1星分
      // 评价5星：+2星分
      var starAdd = 0
      if (score === 4) {
        starAdd = 1
      } else if (score === 5) {
        starAdd = 2
      }

      await db.collection('users').where({ _openid: targetId }).update({
        data: {
          rating: newRating,
          ratingCount: _.inc(1),
          starPoints: _.inc(starAdd)
        }
      })
    }

    return { code: 0, msg: '评价成功' }
  } catch (err) {
    return { code: -1, msg: '评价失败', err: err.message }
  }
}
