const cloud = require('wx-server-sdk')
cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV })
const db = cloud.database()
const _ = db.command
const $ = db.command.aggregate

exports.main = async function(event, context) {
  try {
    const [paidCountResult, userCountResult, reviewsResult] = await Promise.all([
      db.collection('orders').where({ status: 'paid' }).count(),
      db.collection('users').count(),
      db.collection('reviews').limit(100).get()
    ])

    const totalHelp = paidCountResult.total
    const activeUsers = userCountResult.total

    let satisfaction = 98.5
    const reviews = reviewsResult.data
    if (reviews.length > 0) {
      const totalScore = reviews.reduce(function(sum, r) { return sum + (r.score || 0) }, 0)
      const avgScore = totalScore / reviews.length
      satisfaction = Math.round((avgScore / 5 * 100) * 10) / 10
    }

    return {
      code: 0,
      msg: '获取成功',
      data: {
        totalHelp: totalHelp,
        activeUsers: activeUsers,
        satisfaction: satisfaction
      }
    }
  } catch (err) {
    return { code: -1, msg: '获取失败', err: err.message }
  }
}
