// 云函数：用户登录/注册
// registerWithPhone: 首次注册（手机号，昵称=用户+尾号4位）
// autoCreate: 查找已有用户（不自动创建）
// updateProfile: 更新资料
// restoreCredit: 恢复信誉分
const cloud = require('wx-server-sdk')
cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV })
const db = cloud.database()
const _ = db.command

// 内容审核 - 违规关键词过滤
var BAD_WORDS = [
  '色情', '赌博', '嫖娼', '卖淫', '开房', '约炮', '裸聊', '性交',
  '赌场', '赌资', '下注', '赌狗', '网赌', '百家乐', '老虎机', '百家了',
  '代孕', '买卖器官', '毒品', '大麻', '冰毒', '海洛因', '摇头丸',
  '传销', '洗钱', '诈骗', '钓鱼', '刷单', '刷单返利', '色诱',
  '法轮功', '邪教', '恐怖', '炸弹', '枪支', '弹药',
  '假发票', '发票代开', '办证', '假证', '身份证买卖',
  '微信解封', '解封微信', '活体', '偷拍', '迷药',
  'av', ' Adult Video', 'porn', 'xxx', 'sex',
  '菠菜', '彩票预测', '内幕消息', '稳赚不赔',
  '色诱', '约茶', '外围', '出台', '兼职色',
  '借贷', '网贷', '套路贷', '裸贷', '肉偿',
  '私彩', '六合彩', '时时彩', '北京赛车',
  '加群', '进群', 'QQ群', '加qq'
]

function filterContent(text) {
  var lower = text.toLowerCase()
  for (var i = 0; i < BAD_WORDS.length; i++) {
    if (lower.indexOf(BAD_WORDS[i].toLowerCase()) >= 0) {
      return { passed: false, word: BAD_WORDS[i] }
    }
  }
  return { passed: true }
}

async function checkIsAdmin(openid) {
  try {
    const userRes = await db.collection('users').where({ _openid: openid }).get()
    if (userRes.data && userRes.data.length > 0) {
      var user = userRes.data[0]
      var isAdmin = user.isAdmin || user['isAdmin ']
      var isManager = user.isManager || user['isManager ']
      return !!(isAdmin || isManager)
    }
  } catch (e) {}
  return false
}

exports.main = async function(event, context) {
  const wxContext = cloud.getWXContext()
  const openid = wxContext.OPENID

  // ========== action 路由 ==========

  // 首次注册：填手机号 → 自动创建用户，昵称=用户+手机尾号4位
  if (event.action === 'registerWithPhone') {
    try {
      var phone = (event.phone || '').trim()
      if (!phone || phone.length !== 11) {
        return { code: -1, msg: '请输入正确的11位手机号' }
      }

      // 先查是否已注册
      var existingUser = null
      // 方式1：用 _id 查
      if (event._id) {
        try {
          const res = await db.collection('users').doc(event._id).get()
          if (res.data) existingUser = res.data
        } catch(e) {}
      }
      // 方式2：用 _openid 查
      if (!existingUser) {
        try {
          const res = await db.collection('users').where({ _openid: openid }).get()
          if (res.data && res.data.length > 0) existingUser = res.data[0]
        } catch(e) {}
      }

      if (existingUser) {
        // 已存在，更新手机号
        await db.collection('users').doc(existingUser._id).update({ data: { phone: phone } })
        const updated = await db.collection('users').doc(existingUser._id).get()
        return { code: 0, data: Object.assign({}, updated.data, { _openid: openid, _id: existingUser._id, isNew: false }) }
      }

      // 新用户：昵称 = 用户 + 手机尾号4位
      var lastFour = phone.substring(7)
      var nickName = '用户' + lastFour
      const newUser = {
        _openid: openid,
        nickName: nickName,
        phone: phone,
        avatar: '',
        avatarUrl: '',
        gender: 0,
        building: '',
        floor: '',
        room: '',
        wechat: '',
        isVerified: false,
        creditScore: 100,
        rating: 0,
        ratingCount: 0,
        orderCount: 0,
        helpCount: 0,
        balance: 0,
        starPoints: 0,
        school: event.school || '广东江门中医药职业学院',
        createTime: db.serverDate()
      }
      const addResult = await db.collection('users').add({ data: newUser })
      return { code: 0, data: Object.assign({}, newUser, { _id: addResult._id, isNew: true }) }
    } catch (err) {
      return { code: -1, msg: '注册失败', err: err.message }
    }
  }

  if (event.action === 'getUserInfo') {
    try {
      var targetOpenid = event.openid || openid
      var isSelf = targetOpenid === openid
      var isAdmin = await checkIsAdmin(openid)
      var res = await db.collection('users').where({ _openid: targetOpenid }).get()
      if (res.data && res.data.length > 0) {
        var user = res.data[0]
        if (isSelf || isAdmin) {
          return { code: 0, data: user }
        }
        var publicProfile = {
          nickName: user.nickName || '匿名用户',
          avatarUrl: user.avatarUrl || '',
          building: user.building || '',
          floor: user.floor || '',
          room: user.room || '',
          rating: user.rating || 0,
          ratingCount: user.ratingCount || 0,
          orderCount: user.orderCount || 0,
          helpCount: user.helpCount || 0,
          isVerified: user.isVerified || false,
          starPoints: user.starPoints || 0,
          isAdmin: !!(user.isAdmin || user['isAdmin ']),
          isManager: !!(user.isManager || user['isManager '])
        }
        return { code: 0, data: publicProfile }
      }
      return { code: -1, msg: '用户不存在' }
    } catch (err) {
      return { code: -1, msg: '查询失败', err: err.message }
    }
  }

  if (event.action === 'autoCreate' || !event.action) {
    try {
      // 并行查询：同时按 _id 和 _openid 查，减少延迟
      var promises = []
      if (event._id) {
        promises.push(db.collection('users').doc(event._id).get().then(function(res) { return res.data }).catch(function() { return null }))
      }
      promises.push(db.collection('users').where({ _openid: openid }).get().then(function(res) { return (res.data && res.data.length > 0) ? res.data[0] : null }).catch(function() { return null }))

      var results = await Promise.all(promises)
      var existingUser = null
      for (var i = 0; i < results.length; i++) {
        if (results[i]) { existingUser = results[i]; break }
      }

      if (existingUser) {
        return { code: 0, data: Object.assign({}, existingUser, { _openid: openid, isNew: false }) }
      }

      // 没找到，返回未注册状态
      return { code: 0, data: { _openid: openid, isNew: true, needRegister: true } }
    } catch (err) {
      return { code: -1, msg: '查询失败', err: err.message }
    }
  }

  // 更新用户资料
  if (event.action === 'updateProfile') {
    try {
      var user = null

      if (event._id) {
        try {
          const res = await db.collection('users').doc(event._id).get()
          if (res.data) user = res.data
        } catch(e) {}
      }

      if (!user) {
        try {
          const res = await db.collection('users').where({ _openid: openid }).get()
          if (res.data && res.data.length > 0) user = res.data[0]
        } catch(e) {}
      }

      if (!user) {
        return { code: -1, msg: '用户不存在，请先关闭小程序重新打开' }
      }

      const updateData = {}
      // 昵称允许改为空（保持原来的），但传了非空就更新
      if (event.nickName !== undefined) {
        updateData.nickName = event.nickName
      }
      if (event.phone !== undefined) {
        updateData.phone = event.phone
      }
      if (event.avatar !== undefined && event.avatar !== '') {
        updateData.avatar = event.avatar
      }

      if (Object.keys(updateData).length === 0) {
        return { code: 0, data: Object.assign({}, user, { _openid: openid }) }
      }

      await db.collection('users').doc(user._id).update({
        data: updateData
      })

      const updated = await db.collection('users').doc(user._id).get()
      return { code: 0, data: Object.assign({}, updated.data, { _openid: openid, _id: user._id }) }
    } catch (err) {
      return { code: -1, msg: '更新失败', err: err.message }
    }
  }

  // 恢复信誉分
  if (event.action === 'restoreCredit') {
    try {
      var user = null
      try {
        const res = await db.collection('users').where({ _openid: openid }).get()
        if (res.data && res.data.length > 0) user = res.data[0]
      } catch(e) {}

      if (!user) return { code: -1, msg: '用户不存在' }

      var currentScore = user.creditScore || 100
      if (currentScore >= 100) return { code: 0, data: user, msg: '信誉分已满' }

      var newScore = Math.min(100, currentScore + 5)
      await db.collection('users').doc(user._id).update({
        data: { creditScore: newScore }
      })

      const updated = await db.collection('users').doc(user._id).get()
      return { code: 0, data: updated.data }
    } catch (err) {
      return { code: -1, msg: '恢复失败' }
    }
  }

  // 扣除信誉分（管理员操作）
  if (event.action === 'deductCredit') {
    try {
      var isAdmin = await checkIsAdmin(openid)
      if (!isAdmin) return { code: -1, msg: '无权限操作' }
      if (!event.userId) return { code: -1, msg: '缺少用户ID' }
      var score = parseInt(event.score || 0)
      if (!score || score <= 0 || score > 50) return { code: -1, msg: '扣除分数需在1-50之间' }

      const userRes = await db.collection('users').where({ _openid: event.userId }).get()
      if (!userRes.data || userRes.data.length === 0) {
        return { code: -1, msg: '用户不存在' }
      }
      var user = userRes.data[0]
      var currentScore = user.creditScore || 100
      var newScore = Math.max(0, currentScore - score)
      await db.collection('users').doc(user._id).update({
        data: { creditScore: newScore }
      })
      return { code: 0, data: { creditScore: newScore } }
    } catch (err) {
      return { code: -1, msg: '扣分失败', err: err.message }
    }
  }

  // 发布公告
  if (event.action === 'publishNotice') {
    try {
      var isAdmin = await checkIsAdmin(openid)
      if (!isAdmin) return { code: -1, msg: '无权限操作' }
      var duration = event.duration || 24
      var notice = {
        content: event.content || '',
        duration: duration,
        publisherRole: event.publisherRole || 'admin',
        school: event.school || '广东江门中医药职业学院',
        expireTime: db.serverDate({ offset: duration * 3600000 }),
        _openid: openid,
        createTime: db.serverDate()
      }
      const res = await db.collection('notices').add({ data: notice })
      return { code: 0, data: { _id: res._id } }
    } catch (err) {
      return { code: -1, msg: '发布失败', err: err.message }
    }
  }

  // 删除公告
  if (event.action === 'deleteNotice') {
    try {
      var isAdmin = await checkIsAdmin(openid)
      if (!isAdmin) return { code: -1, msg: '无权限操作' }
      if (!event._id) return { code: -1, msg: '缺少公告ID' }
      await db.collection('notices').doc(event._id).remove()
      return { code: 0, msg: '删除成功' }
    } catch (err) {
      return { code: -1, msg: '删除失败', err: err.message }
    }
  }

  // 获取订单详情（管理员用，绕过权限）
  if (event.action === 'getOrderDetail') {
    try {
      var isAdmin = await checkIsAdmin(openid)
      if (!isAdmin) return { code: -1, msg: '无权限操作' }
      if (!event._id) return { code: -1, msg: '缺少订单ID' }
      const res = await db.collection('orders').doc(event._id).get()
      return { code: 0, data: res.data }
    } catch (err) {
      return { code: -1, msg: '订单不存在', err: err.message }
    }
  }

  // 获取有效公告（未过期）
  if (event.action === 'getNotices') {
    try {
      var school = event.school || '广东江门中医药职业学院'
      const res = await db.collection('notices').where({ school: school }).orderBy('createTime', 'desc').limit(10).get()
      const now = Date.now()
      const active = []
      for (var i = 0; i < res.data.length; i++) {
        var n = res.data[i]
        if (n.duration >= 720) {
          active.push(n)
        } else {
          var expireTime = n.expireTime ? new Date(n.expireTime).getTime() : 0
          if (expireTime > now) {
            active.push(n)
          }
        }
      }
      return { code: 0, data: active }
    } catch (err) {
      return { code: 0, data: [] }
    }
  }

  // 定时清理过期数据（保留用户统计信息）
  if (event.action === 'cleanExpiredData') {
    try {
      var thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 3600000)
      var results = { orders: 0, messages: 0, reviews: 0, notices: 0, posts: 0 }

      // 1. 清理30天前的已完成订单（paid/cancelled状态）
      try {
        while (true) {
          var res = await db.collection('orders').where({
            status: _.in(['paid', 'cancelled']),
            createTime: _.lt(thirtyDaysAgo)
          }).limit(100).get()
          if (!res.data || res.data.length === 0) break
          var ids = res.data.map(function(item) { return item._id })
          var delRes = await db.collection('orders').where({ _id: _.in(ids) }).remove()
          results.orders += (delRes.stats && delRes.stats.removed) || ids.length
          if (res.data.length < 100) break
        }
      } catch(e) {}

      // 2. 清理30天前的聊天记录
      try {
        while (true) {
          var res = await db.collection('messages').where({
            createTime: _.lt(thirtyDaysAgo)
          }).limit(100).get()
          if (!res.data || res.data.length === 0) break
          var ids = res.data.map(function(item) { return item._id })
          var delRes = await db.collection('messages').where({ _id: _.in(ids) }).remove()
          results.messages += (delRes.stats && delRes.stats.removed) || ids.length
          if (res.data.length < 100) break
        }
      } catch(e) {}

      // 3. 清理30天前的评价记录（评价分数已经算进用户星分了，记录本身可以删）
      try {
        while (true) {
          var res = await db.collection('reviews').where({
            createTime: _.lt(thirtyDaysAgo)
          }).limit(100).get()
          if (!res.data || res.data.length === 0) break
          var ids = res.data.map(function(item) { return item._id })
          var delRes = await db.collection('reviews').where({ _id: _.in(ids) }).remove()
          results.reviews += (delRes.stats && delRes.stats.removed) || ids.length
          if (res.data.length < 100) break
        }
      } catch(e) {}

      // 4. 清理已过期的公告（非永久的）
      try {
        while (true) {
          var res = await db.collection('notices').where({
            duration: _.lt(720),
            expireTime: _.lt(thirtyDaysAgo)
          }).limit(100).get()
          if (!res.data || res.data.length === 0) break
          var ids = res.data.map(function(item) { return item._id })
          var delRes = await db.collection('notices').where({ _id: _.in(ids) }).remove()
          results.notices += (delRes.stats && delRes.stats.removed) || ids.length
          if (res.data.length < 100) break
        }
      } catch(e) {}

      // 5. 清理30天前的帖子
      try {
        while (true) {
          var res = await db.collection('posts').where({
            createTime: _.lt(thirtyDaysAgo)
          }).limit(100).get()
          if (!res.data || res.data.length === 0) break
          var ids = res.data.map(function(item) { return item._id })
          var delRes = await db.collection('posts').where({ _id: _.in(ids) }).remove()
          results.posts += (delRes.stats && delRes.stats.removed) || ids.length
          if (res.data.length < 100) break
        }
      } catch(e) {}

      // 注意：不删除 users 集合的任何数据
      // orderCount、helpCount、starPoints、creditScore、rating 等统计信息永久保留

      return {
        code: 0,
        msg: '清理完成',
        data: results
      }
    } catch (err) {
      return { code: -1, msg: '清理失败', err: err.message }
    }
  }

  // ========== 吐槽广场 ==========

  // 获取帖子列表（分页）
  if (event.action === 'getPosts') {
    try {
      var page = event.page || 0
      var limit = Math.min(event.limit || 15, 20)
      var skip = page * limit
      var school = event.school || '广东江门中医药职业学院'
      const res = await db.collection('posts').where({ school: school }).orderBy('createTime', 'desc').skip(skip).limit(limit).get()
      var posts = res.data.map(function(p) {
        p.viewCount = (p.viewers && p.viewers.length) || 0
        p.isMine = !!(p._openid && event.myOpenId && p._openid === event.myOpenId)
        delete p.viewers
        return p
      })
      // 在 return 之前，将置顶帖子提前
      var pinned = posts.filter(function(p) { return p.isPinned })
      var normal = posts.filter(function(p) { return !p.isPinned })
      posts = pinned.concat(normal)
      return { code: 0, data: posts }
    } catch (err) {
      return { code: -1, msg: '获取失败', err: err.message }
    }
  }

  // 获取帖子详情
  if (event.action === 'getPostDetail') {
    try {
      if (!event._id) return { code: -1, msg: '缺少帖子ID' }
      const res = await db.collection('posts').doc(event._id).get()
      var post = res.data
      post.isMine = !!(post._openid && event.myOpenId && post._openid === event.myOpenId)
      post.likeCount = post.likeCount || 0
      var likers = post.likers || []
      post.isLiked = !!(event.myOpenId && likers.indexOf(event.myOpenId) > -1)
      var replies = post.replies || []
      for (var i = 0; i < replies.length; i++) {
        replies[i].isMine = !!(replies[i]._openid && event.myOpenId && replies[i]._openid === event.myOpenId)
      }
      post.replies = replies
      return { code: 0, data: post }
    } catch (err) {
      return { code: -1, msg: '帖子不存在', err: err.message }
    }
  }

  // 点赞帖子
  if (event.action === 'likePost') {
    try {
      if (!event._id) return { code: -1, msg: '缺少帖子ID' }
      const postRes = await db.collection('posts').doc(event._id).get()
      var post = postRes.data
      var likers = post.likers || []
      if (likers.indexOf(openid) > -1) {
        return { code: -1, msg: '已经点赞过了' }
      }
      likers.push(openid)
      await db.collection('posts').doc(event._id).update({
        data: {
          likers: likers,
          likeCount: likers.length
        }
      })
      return { code: 0, data: { likeCount: likers.length } }
    } catch (err) {
      return { code: -1, msg: '点赞失败', err: err.message }
    }
  }

  // 点赞回复
  if (event.action === 'likeReply') {
    try {
      if (!event._id) return { code: -1, msg: '缺少帖子ID' }
      if (event.replyIndex === undefined) return { code: -1, msg: '缺少回复索引' }
      const postRes = await db.collection('posts').doc(event._id).get()
      var post = postRes.data
      var replies = post.replies || []
      var idx = event.replyIndex
      if (idx < 0 || idx >= replies.length) {
        return { code: -1, msg: '回复不存在' }
      }
      var likers = replies[idx].likers || []
      if (likers.indexOf(openid) > -1) {
        return { code: -1, msg: '已经点赞过了' }
      }
      likers.push(openid)
      replies[idx].likers = likers
      replies[idx].likeCount = likers.length
      var updateData = {}
      updateData['replies.' + idx + '.likers'] = likers
      updateData['replies.' + idx + '.likeCount'] = likers.length
      await db.collection('posts').doc(event._id).update({ data: updateData })
      return { code: 0, data: { likeCount: likers.length } }
    } catch (err) {
      return { code: -1, msg: '点赞失败', err: err.message }
    }
  }

  // 记录帖子浏览（每人只记一次）
  if (event.action === 'viewPost') {
    try {
      if (!event._id) return { code: 0 }
      var postRes = await db.collection('posts').doc(event._id).get()
      var post = postRes.data
      var viewers = post.viewers || []
      // 检查是否已记录过
      if (viewers.indexOf(openid) === -1) {
        viewers.push(openid)
        await db.collection('posts').doc(event._id).update({
          data: { viewers: viewers, viewCount: viewers.length }
        })
      }
      return { code: 0 }
    } catch (err) {
      return { code: 0 } // 静默失败，不影响体验
    }
  }

  // 发帖
  if (event.action === 'createPost') {
    try {
      var content = (event.content || '').trim()
      if (!content) return { code: -1, msg: '内容不能为空' }
      if (content.length > 500) return { code: -1, msg: '内容不能超过500字' }
      // 内容审核 - 过滤违规关键词
      var filterResult = filterContent(content)
      if (!filterResult.passed) {
        return { code: -1, msg: '内容包含违规信息，请修改后重试' }
      }
      const post = {
        content: content,
        authorName: event.authorName || '匿名用户',
        authorPhone: event.authorPhone || '',
        avatarColor: event.avatarColor || '#0EA5E9',
        starPoints: event.starPoints || 0,
        isAdmin: !!event.isAdmin,
        isManager: !!event.isManager,
        media: event.media || [],
        coverImage: event.coverImage || '',
        school: event.school || '广东江门中医药职业学院',
        _openid: openid,
        replies: [],
        createTime: db.serverDate()
      }
      const res = await db.collection('posts').add({ data: post })
      return { code: 0, data: { _id: res._id } }
    } catch (err) {
      return { code: -1, msg: '发布失败', err: err.message }
    }
  }

  // 回复帖子
  if (event.action === 'replyPost') {
    try {
      if (!event._id) return { code: -1, msg: '缺少帖子ID' }
      var content = (event.content || '').trim()
      var imageUrls = event.imageUrls || []
      if (!content && imageUrls.length === 0) return { code: -1, msg: '回复内容不能为空' }
      if (content.length > 500) return { code: -1, msg: '回复不能超过500字' }
      // 内容审核 - 过滤违规关键词
      var filterResult = filterContent(content)
      if (!filterResult.passed) {
        return { code: -1, msg: '内容包含违规信息，请修改后重试' }
      }

      // 获取当前回复数作为楼层号
      const postRes = await db.collection('posts').doc(event._id).get()
      var currentReplies = postRes.data.replies || []
      if (currentReplies.length >= 200) {
        return { code: -1, msg: '该帖子回复已满（最多200条）' }
      }
      currentReplies.push({
        content: content,
        imageUrls: imageUrls,
        authorName: event.authorName || '匿名用户',
        authorPhone: event.authorPhone || '',
        avatarColor: event.avatarColor || '#718096',
        starPoints: event.starPoints || 0,
        isAdmin: !!event.isAdmin,
        isManager: !!event.isManager,
        quoteContent: event.quoteContent || '',
        quoteFloor: event.quoteFloor || 0,
        quoteAuthor: event.quoteAuthor || '',
        _openid: openid,
        createTime: new Date()
      })
      await db.collection('posts').doc(event._id).update({
        data: { replies: currentReplies }
      })
      return { code: 0, msg: '回复成功' }
    } catch (err) {
      return { code: -1, msg: '回复失败', err: err.message }
    }
  }

  // 置顶帖子
  if (event.action === 'pinPost') {
    try {
      var isAdmin = await checkIsAdmin(openid)
      if (!isAdmin) return { code: -1, msg: '无权限操作' }
      if (!event._id) return { code: -1, msg: '缺少帖子ID' }
      await db.collection('posts').doc(event._id).update({
        data: { isPinned: true, pinnedTime: db.serverDate() }
      })
      return { code: 0, msg: '已置顶' }
    } catch (err) {
      return { code: -1, msg: '操作失败', err: err.message }
    }
  }

  // 删除帖子（仅创建者或管理员）
  if (event.action === 'deletePost') {
    try {
      if (!event._id) return { code: -1, msg: '缺少帖子ID' }
      var postRes = await db.collection('posts').doc(event._id).get()
      var post = postRes.data
      // 检查是否是创建者或管理员
      var userRes = await db.collection('users').where({ _openid: openid }).get()
      var user = (userRes.data && userRes.data.length > 0) ? userRes.data[0] : {}
      if (post._openid !== openid && !user.isAdmin && !user.isManager) {
        return { code: -1, msg: '无权删除' }
      }
      await db.collection('posts').doc(event._id).remove()
      return { code: 0, msg: '删除成功' }
    } catch (err) {
      return { code: -1, msg: '删除失败', err: err.message }
    }
  }

  // 删除帖子中的某条回复（仅管理员可删）
  if (event.action === 'deleteReply') {
    try {
      if (!event._id || event.index === undefined || event.index === null) {
        return { code: -1, msg: '缺少参数' }
      }
      var isAdmin = await checkIsAdmin(openid)
      if (!isAdmin) return { code: -1, msg: '无权限操作' }
      var postRes = await db.collection('posts').doc(event._id).get()
      var replies = postRes.data.replies || []
      if (event.index >= 0 && event.index < replies.length) {
        replies.splice(event.index, 1)
        await db.collection('posts').doc(event._id).update({ data: { replies: replies } })
        return { code: 0, msg: '删除成功' }
      }
      return { code: -1, msg: '回复不存在' }
    } catch (err) {
      return { code: -1, msg: '删除失败', err: err.message }
    }
  }

  // 按关键词搜索帖子
  if (event.action === 'searchPosts') {
    try {
      var keyword = (event.keyword || '').trim()
      if (!keyword) return { code: 0, data: [] }
      const _ = db.command
      const res = await db.collection('posts').where(
        _.or([
          { content: db.RegExp({ regexp: keyword, options: 'i' }) },
          { authorName: db.RegExp({ regexp: keyword, options: 'i' }) }
        ])
      ).orderBy('createTime', 'desc').limit(20).get()
      return { code: 0, data: res.data }
    } catch (err) {
      return { code: -1, msg: '搜索失败', err: err.message }
    }
  }

  // ========== 用户反馈 ==========

  // 提交反馈
  if (event.action === 'submitFeedback') {
    try {
      var content = (event.content || '').trim()
      if (!content) return { code: -1, msg: '反馈内容不能为空' }
      const feedback = {
        type: event.type || '其他',
        content: content,
        contact: event.contact || '',
        status: 'pending', // pending/processed
        school: event.school || '广东江门中医药职业学院',
        _openid: openid,
        createTime: db.serverDate()
      }
      const res = await db.collection('feedback').add({ data: feedback })
      return { code: 0, msg: '提交成功' }
    } catch (err) {
      return { code: -1, msg: '提交失败', err: err.message }
    }
  }

  // 获取反馈列表
  if (event.action === 'getFeedbacks') {
    try {
      var status = event.status || ''
      var school = event.school || '广东江门中医药职业学院'
      var query = { school: school }
      if (status) query.status = status
      const res = await db.collection('feedback').orderBy('createTime', 'desc').where(query).limit(50).get()
      return { code: 0, data: res.data }
    } catch (err) {
      return { code: -1, msg: '获取失败', err: err.message }
    }
  }

  // 标记反馈已处理
  if (event.action === 'processFeedback') {
    try {
      var isAdmin = await checkIsAdmin(openid)
      if (!isAdmin) return { code: -1, msg: '无权限操作' }
      if (!event._id) return { code: -1, msg: '缺少反馈ID' }
      await db.collection('feedback').doc(event._id).update({
        data: { status: 'processed' }
      })
      return { code: 0, msg: '已处理' }
    } catch (err) {
      return { code: -1, msg: '操作失败', err: err.message }
    }
  }

  // 删除反馈
  if (event.action === 'deleteFeedback') {
    try {
      var isAdmin = await checkIsAdmin(openid)
      if (!isAdmin) return { code: -1, msg: '无权限操作' }
      if (!event._id) return { code: -1, msg: '缺少反馈ID' }
      await db.collection('feedback').doc(event._id).remove()
      return { code: 0, msg: '删除成功' }
    } catch (err) {
      return { code: -1, msg: '删除失败', err: err.message }
    }
  }

  // ========== 投诉管理 ==========

  // 获取与我相关的订单（投诉用）
  if (event.action === 'getMyRelatedOrders') {
    try {
      var myOpenId = event._openid || openid
      const _ = db.command
      const res = await db.collection('orders').where(
        _.or([
          { publisherId: myOpenId },
          { acceptorId: myOpenId }
        ])
      ).orderBy('createTime', 'desc').limit(30).get()
      return { code: 0, data: res.data }
    } catch (err) {
      return { code: -1, msg: '获取失败', err: err.message }
    }
  }

  // 提交投诉
  if (event.action === 'submitComplaint') {
    try {
      var content = (event.content || '').trim()
      if (!content) return { code: -1, msg: '投诉内容不能为空' }
      if (!event.orderId) return { code: -1, msg: '请选择关联订单' }
      if (!event.targetUserId) return { code: -1, msg: '投诉对象不能为空' }
      const complaint = {
        orderId: event.orderId,
        orderNo: event.orderNo || '',
        targetUserId: event.targetUserId,
        targetUserName: event.targetUserName || '未知用户',
        complaintType: event.complaintType || '',
        content: content,
        complainantName: event.complainantName || '用户',
        complainantPhone: event.complainantPhone || '',
        status: 'pending', // pending/resolved/rejected
        school: event.school || '广东江门中医药职业学院',
        _openid: openid,
        createTime: db.serverDate()
      }
      const res = await db.collection('complaints').add({ data: complaint })
      return { code: 0, msg: '投诉已提交' }
    } catch (err) {
      return { code: -1, msg: '提交失败', err: err.message }
    }
  }

  // 获取投诉列表（管理用）
  if (event.action === 'getComplaints') {
    try {
      var status = event.status || ''
      var school = event.school || '广东江门中医药职业学院'
      var query = { school: school }
      if (status) query.status = status
      const res = await db.collection('complaints').orderBy('createTime', 'desc').where(query).limit(50).get()
      return { code: 0, data: res.data }
    } catch (err) {
      return { code: -1, msg: '获取失败', err: err.message }
    }
  }

  // 处理投诉（可扣分，自动通知双方）
  if (event.action === 'resolveComplaint') {
    try {
      var isAdmin = await checkIsAdmin(openid)
      if (!isAdmin) return { code: -1, msg: '无权限操作' }
      if (!event._id) return { code: -1, msg: '缺少投诉ID' }
      var deductScore = event.deductScore || 0
      var resolveNote = event.resolveNote || ''
      
      // 获取投诉详情
      var complaintRes = await db.collection('complaints').doc(event._id).get()
      var complaint = complaintRes.data
      
      // 标记投诉已处理
      var updateData = {
        status: 'resolved',
        resolveTime: new Date(),
        deductScore: deductScore,
        resolveNote: resolveNote
      }
      await db.collection('complaints').doc(event._id).update({ data: updateData })
      
      var results = { resolved: true }
      
      // 如果需要扣分，更新被投诉者信用分
      if (deductScore > 0 && complaint.targetId) {
        var targetUserRes = await db.collection('users').where({ _openid: complaint.targetId }).get()
        if (targetUserRes.data && targetUserRes.data.length > 0) {
          var targetUser = targetUserRes.data[0]
          var currentCredit = targetUser.creditScore || 100
          var newCredit = Math.max(0, currentCredit - deductScore)
          await db.collection('users').where({ _openid: complaint.targetId }).update({
            data: { creditScore: newCredit }
          })
          results.newCreditScore = newCredit

          // 给被投诉者发系统通知
          var noteText = resolveNote ? '（' + resolveNote + '）' : ''
          await db.collection('system_notifications').add({
            data: {
              userId: complaint.targetId,
              title: '投诉处理通知',
              content: '您因被投诉，信用分被扣除' + deductScore + '分（当前：' + newCredit + '分）' + noteText + '。请遵守平台规则，保持良好信用。',
              type: 'complaint_result',
              isRead: false,
              createTime: db.serverDate()
            }
          })
        }
      }
      
      // 给投诉者发通知（告知处理结果）
      if (complaint.complainantId) {
        var notifyContent = deductScore > 0
          ? '您对' + (complaint.targetUserName || '该用户') + '的投诉已处理，经核实对其扣除' + deductScore + '信用分。感谢您的反馈。'
          : '您对' + (complaint.targetUserName || '该用户') + '的投诉已处理，经核实暂不构成违规，未做处罚。感谢您的反馈。'
        await db.collection('system_notifications').add({
          data: {
            userId: complaint.complainantId,
            title: '投诉处理结果',
            content: notifyContent,
            type: 'complaint_result',
            isRead: false,
            createTime: db.serverDate()
          }
        })
      }
      
      return { code: 0, msg: '处理成功', data: results }
    } catch (err) {
      return { code: -1, msg: '处理失败', err: err.message }
    }
  }

  // 删除投诉
  if (event.action === 'deleteComplaint') {
    try {
      var isAdmin = await checkIsAdmin(openid)
      if (!isAdmin) return { code: -1, msg: '无权限操作' }
      if (!event._id) return { code: -1, msg: '缺少投诉ID' }
      await db.collection('complaints').doc(event._id).remove()
      return { code: 0, msg: '删除成功' }
    } catch (err) {
      return { code: -1, msg: '删除失败', err: err.message }
    }
  }

  // ========== 系统通知 ==========

  // 搜索订单（通知用）
  if (event.action === 'searchOrders') {
    try {
      var keyword = (event.keyword || '').trim()
      if (!keyword) return { code: 0, data: [] }
      const _ = db.command
      const res = await db.collection('orders').where(
        _.or([
          { orderNo: db.RegExp({ regexp: keyword, options: 'i' }) },
          { remark: db.RegExp({ regexp: keyword, options: 'i' }) }
        ])
      ).limit(10).get()
      return { code: 0, data: res.data }
    } catch (err) {
      return { code: -1, msg: '搜索失败', err: err.message }
    }
  }

  // 发送系统通知
  if (event.action === 'sendSystemNotification') {
    try {
      var isAdmin = await checkIsAdmin(openid)
      if (!isAdmin) return { code: -1, msg: '无权限操作' }
      var title = (event.title || '').trim()
      var content = (event.content || '').trim()
      if (!title || !content) return { code: -1, msg: '标题和内容不能为空' }
      
      var targetType = event.targetType || 'all'
      var targetUserIds = event.targetUserIds || []
      
      if (targetType === 'all') {
        // 分批获取所有用户，避免超过100条限制
        var allUserIds = []
        var batchSkip = 0
        var hasMore = true
        while (hasMore) {
          var batch = await db.collection('users').skip(batchSkip).limit(100).field({ _openid: true }).get()
          for (var bi = 0; bi < batch.data.length; bi++) {
            if (batch.data[bi]._openid) allUserIds.push(batch.data[bi]._openid)
          }
          hasMore = batch.data.length === 100
          batchSkip += 100
        }
        var count = 0
        for (var i = 0; i < allUserIds.length; i++) {
          await db.collection('system_notifications').add({
            data: {
              userId: allUserIds[i],
              title: title,
              content: content,
              type: 'system',
              isRead: false,
              createTime: db.serverDate()
            }
          })
          count++
        }
        return { code: 0, msg: '已通知' + count + '人' }
      } else if (targetType === 'users' && targetUserIds.length > 0) {
        var count2 = 0
        for (var j = 0; j < targetUserIds.length; j++) {
          if (targetUserIds[j]) {
            await db.collection('system_notifications').add({
              data: {
                userId: targetUserIds[j],
                title: title,
                content: content,
                type: 'system',
                isRead: false,
                createTime: db.serverDate()
              }
            })
            count2++
          }
        }
        return { code: 0, msg: '已通知' + count2 + '人' }
      } else {
        return { code: -1, msg: '请选择发送对象' }
      }
    } catch (err) {
      return { code: -1, msg: '发送失败', err: err.message }
    }
  }

  // 获取系统通知
  if (event.action === 'getSystemNotifications') {
    try {
      var userInfo = event.userInfo || {}
      var userId = userInfo._openid || openid
      const res = await db.collection('system_notifications').where({ userId: userId }).orderBy('createTime', 'desc').limit(20).get()
      return { code: 0, data: res.data }
    } catch (err) {
      return { code: -1, msg: '获取失败', err: err.message }
    }
  }

  // 标记通知已读
  if (event.action === 'markNotificationRead') {
    try {
      if (!event._id) return { code: -1, msg: '缺少ID' }
      await db.collection('system_notifications').doc(event._id).update({
        data: { isRead: true }
      })
      return { code: 0, msg: '已读' }
    } catch (err) {
      return { code: -1, msg: '操作失败', err: err.message }
    }
  }

  // 获取未读通知数
  if (event.action === 'getUnreadNotifyCount') {
    try {
      var userInfo2 = event.userInfo || {}
      var userId2 = userInfo2._openid || openid
      const _ = db.command
      const res = await db.collection('system_notifications').where({ userId: userId2, isRead: false }).count()
      return { code: 0, data: res.total }
    } catch (err) {
      return { code: -1, msg: '获取失败', err: err.message }
    }
  }

  // ========== 客服配置 ==========

  // 获取客服列表
  if (event.action === 'getServiceAccounts') {
    try {
      const _ = db.command
      const res = await db.collection('system_config').doc('service_accounts').get()
      return { code: 0, data: (res.data && res.data.accounts) || [] }
    } catch (err) {
      return { code: 0, data: [] }
    }
  }

  // 保存客服列表（管理员）
  if (event.action === 'saveServiceAccounts') {
    try {
      var isAdmin = await checkIsAdmin(openid)
      if (!isAdmin) return { code: -1, msg: '无权限操作' }
      var accounts = event.accounts || []
      await db.collection('system_config').doc('service_accounts').set({
        data: { accounts: accounts }
      })
      return { code: 0, msg: '保存成功' }
    } catch (err) {
      return { code: -1, msg: '保存失败', err: err.message }
    }
  }

  // 封禁用户（管理员操作）
  if (event.action === 'banUser') {
    try {
      var isAdmin = await checkIsAdmin(openid)
      if (!isAdmin) return { code: -1, msg: '无权限操作' }
      if (!event.userId) return { code: -1, msg: '缺少用户ID' }
      // 不能封禁管理员
      var targetUser = await db.collection('users').doc(event.userId).get()
      if (targetUser.data) {
        var tIsAdmin = targetUser.data.isAdmin || targetUser.data['isAdmin ']
        var tIsManager = targetUser.data.isManager || targetUser.data['isManager ']
        if (tIsAdmin || tIsManager) return { code: -1, msg: '不能封禁管理员' }
      }
      await db.collection('users').doc(event.userId).update({
        data: { isBanned: true, creditScore: 0 }
      })
      return { code: 0, msg: '已封禁' }
    } catch (err) {
      return { code: -1, msg: '封禁失败', err: err.message }
    }
  }

  // 解封用户（管理员操作）
  if (event.action === 'unbanUser') {
    try {
      var isAdmin = await checkIsAdmin(openid)
      if (!isAdmin) return { code: -1, msg: '无权限操作' }
      if (!event.userId) return { code: -1, msg: '缺少用户ID' }
      await db.collection('users').doc(event.userId).update({
        data: { isBanned: false, creditScore: 60 }
      })
      return { code: 0, msg: '已解封' }
    } catch (err) {
      return { code: -1, msg: '解封失败', err: err.message }
    }
  }

  return { code: -1, msg: '未知操作' }
}
